/// <summary>
/// PricingAttribute of table <c>RetailSalesTable</c> field RetailStoreId.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::SalesTable, GUPPricingAttributeSourceLevel::Header)]
/// [GUPPricingAttributeFieldsDiscovery(fieldStr(RetailStoreTable, StoreNumber))]
class GUPPricingAttributeRetailSalesTableRetailStoreId extends GUPPricingAttributeRetailSalesTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(RetailSalesTable, RetailStoreId);
}

public Set getAllowedValues()
{
    RetailStoreTable    retailStoreTable;
    var                 ret = new Set(Types::String);

    while select StoreNumber from retailStoreTable
    {
        ret.add(retailStoreTable.StoreNumber);
    }

    return ret;
}
